        for skill in effective:
            effective[skill] = int(effective[skill] * (1.0 - penalty_pct))

    return effective, total_weight, max_weight

def generate_random_item(self, leg_num=1, quality_bias=None):
    cat_key = random.choice(list(ITEM_CATEGORIES.keys()))
    cat_data = ITEM_CATEGORIES[cat_key]

    if not quality_bias:
        r = random.random()
        if leg_num == 1:
            tier = "Common" if r < 0.70 else ("Uncommon" if r < 0.95 else "Rare")
        elif leg_num == 2:
            tier = "Common" if r < 0.40 else ("Uncommon" if r < 0.85 else "Rare")
        elif leg_num == 3:
            tier = "Uncommon" if r < 0.50 else ("Rare" if r < 0.90 else "Epic")
        else:
            tier = "Rare" if r < 0.60 else "Epic"
    else:
