import json
from collections import Counter
from game_data import LEGS

super_monsters = {leg['super_monster'] for leg in LEGS}
dungeon_bosses = {d['boss'] for leg in LEGS for d in leg['dungeons']}
dungeon_floors = {m for leg in LEGS for d in leg['dungeons'] for m in d.get('floors', [])}

c = Counter()
raw = Counter()
with open('sim_logs/sim_events.jsonl') as f:
    for line in f:
        e = json.loads(line)
        if e.get('type') != 'DIED':
            continue
        reason = e['details'].get('reason','')
        if reason.startswith('slain by '):
            m = reason[len('slain by '):]
        else:
            m = reason
        raw[m]+=1
        if m in super_monsters:
            c['super_monster'] += 1
        elif m in dungeon_bosses:
            c['dungeon_boss'] += 1
        elif m in dungeon_floors:
            c['dungeon_floor'] += 1
        else:
            c['regular_monster'] += 1

print('Totals by killer type:')
for k,v in c.items():
    print(k, v)
print('total', sum(c.values()))

print('\nTop 10 killers with type:')
for m,n in raw.most_common(10):
    if m in super_monsters:
        t='super_monster'
    elif m in dungeon_bosses:
        t='dungeon_boss'
    elif m in dungeon_floors:
        t='dungeon_floor'
    else:
        t='regular_monster'
    print(f'{m}: {n} ({t})')
